window.QUIZ = (window.QUIZ || []).concat([
  { id: "x-001", ch: 6, sec: "6.4", page: 114, type: "scenario", level: 3,
    q: "A corn grower says: \"My silt loam holds 0.32 at field capacity and 0.14 at wilting point. Roots are at 30 inches, my probe says 70% of the available water is left, and I trigger at 50% depletion. Forecast ETo is 0.28 in/d and my Kc is 1.15. How many days before I have to irrigate?\"",
    opts: ["About 3.4 days", "About 3.9 days", "About 6.0 days", "None, he is already past the trigger"], a: 0,
    why: "AWC = 0.32 − 0.14 = 0.18 in/in, so TAW = 0.18 × 30 = 5.4 in and AD = 0.5 × 5.4 = 2.7 in. With 70% remaining, SWD = 0.30 × 5.4 = 1.62 in. Crop ET = 1.15 × 0.28 = 0.322 in/d, so LD = (2.7 − 1.62)/0.322 = 3.4 days. Using ETo instead of crop ET gives 3.9 days, and using field capacity as if it were AWC gives about 6 days.",
    eq: "6.10", calc: "ld-ed-window", fig: null, table: null },
  { id: "x-002", ch: 6, sec: "6.4", page: 113, type: "scenario", level: 2,
    q: "A grower on sandy loam (field capacity 0.20, wilting point 0.08, volumetric) has a 24 in root zone and uses 50% allowable depletion. Probe readings average 0.14 through the root zone. Rain of 0.25 in is forecast in 3 days. He asks whether he can wait for the rain. What do you tell him?",
    opts: ["Wait for the rain, he still has 1.44 in of allowable depletion left", "Wait 3 days, the 0.25 in of rain will cover the deficit", "Irrigate now, the deficit of 1.44 in already equals the allowable depletion", "Irrigate in about 2 days, the deficit is only half of TAW"], a: 2,
    why: "SWD = (0.20 − 0.14) × 24 = 1.44 in. TAW = (0.20 − 0.08) × 24 = 2.88 in and AD = 0.5 × 2.88 = 1.44 in. LD = (AD − SWD)/ET = 0 days, so the crop is at the trigger now. A light forecast rain does not change that, and \"half of TAW\" is exactly the 50% trigger, not a cushion.",
    eq: "6.10", calc: "eq-6.10-6.11", fig: null, table: null },
  { id: "x-003", ch: 6, sec: "6.4", page: 112, type: "calc", level: 2,
    q: "A field has a 36 in root zone in soil with field capacity 0.27 and wilting point 0.12 (volumetric). The allowable depletion fraction is 0.55. At peak, ETo is 0.26 in/d and Kc is 1.2. What is the longest interval between irrigations without stress?",
    opts: ["About 9.5 days", "About 11.4 days", "About 17.3 days", "About 7.8 days"], a: 0,
    why: "AWC = 0.27 − 0.12 = 0.15 in/in, TAW = 0.15 × 36 = 5.4 in, AD = 0.55 × 5.4 = 2.97 in. ET = 1.2 × 0.26 = 0.312 in/d, so Tmax = 2.97/0.312 = 9.5 days. Dividing by ETo gives 11.4 days, dividing TAW gives 17.3 days, and dividing the minimum balance (2.43 in) gives 7.8 days.",
    eq: "6.8", calc: "eq-6.8", fig: null, table: null },
  { id: "x-004", ch: 6, sec: "6.4", page: 114, type: "scenario", level: 3,
    q: "An alfalfa grower (Kc about 1.0, ETo 0.25 in/d) has a 36 in root zone with AWC 0.16 in/in and uses 50% allowable depletion. His soil check shows 75% of available water remaining. He plans a 1.0 in net irrigation and wants to leave room for 0.5 in of rain. What irrigation window do you give him?",
    opts: ["Start any time up to about 17.3 days", "Start no sooner than about 0.2 days and no later than about 5.8 days", "Wait about 6.0 days, which is past the latest date, so cut the depth", "Start no sooner than about 0.2 days and no later than about 11.5 days"], a: 1,
    why: "TAW = 0.16 × 36 = 5.76 in, AD = 2.88 in, SWD = 0.25 × 5.76 = 1.44 in. LD = (2.88 − 1.44)/0.25 = 5.8 days and ED = (0.5 + 1.0 − 1.44)/0.25 = 0.24 days. Using TAW instead of AD gives 17.3 days, ignoring the current deficit gives an ED of 6.0 days, and dividing AD alone by ET gives 11.5 days.",
    eq: "6.16", calc: "ld-ed-window", fig: null, table: null },
  { id: "x-005", ch: 6, sec: "6.4", page: 116, type: "calc", level: 3,
    q: "A checkbook starts the day at SWD = 1.2 in. Daily crop ET for the next 4 days is 0.28, 0.30, 0.31 and 0.25 in. On day 2 the pivot applies 1.1 in gross with DU = 0.82, and on day 3 it rains 0.6 in. What is the SWD at the end of day 4?",
    opts: ["About 0.64 in", "About 1.44 in", "About 0.24 in", "About 0.84 in"], a: 3,
    why: "The checkbook credits the low quarter depth: dLQ = 0.82 × 1.1 = 0.90 in (Eq. 5.8). Day by day: 1.2 + 0.28 = 1.48, then 1.48 + 0.30 − 0.90 = 0.88, then 0.88 + 0.31 − 0.60 = 0.59, then 0.59 + 0.25 = 0.84 in. Crediting the full 1.1 in gives 0.64 in, and leaving out the rain gives 1.44 in.",
    eq: "6.18", calc: "checkbook", fig: null, table: null },
  { id: "x-006", ch: 6, sec: "6.3", page: 111, type: "calc", level: 3,
    q: "Corn will reach maximum rooting depth of 4 ft at 90 days after emergence, starting from 0.5 ft. On day 40, what is the allowable depletion if AWC is 0.17 in/in and the depletion fraction is 0.5?",
    opts: ["About 2.1 in", "About 4.1 in", "About 4.2 in", "About 1.8 in"], a: 0,
    why: "Rd = 0.5 + (4 − 0.5) × 40/90 = 2.06 ft, or 24.7 in (Eq. 6.6 and 6.7). TAW = 0.17 × 24.7 = 4.19 in and AD = 0.5 × 4.19 = 2.1 in. Using the full 48 in root zone gives 4.1 in, stopping at TAW gives 4.2 in, and scaling 4 ft by 40/90 without the starting depth gives about 1.8 in.",
    eq: "6.7", calc: "eq-6.6-6.7", fig: null, table: null },
  { id: "x-007", ch: 13, sec: "13.5", page: 288, type: "scenario", level: 3,
    q: "A grower's tensiometers in a sandy loam read 40 cb at both 12 and 24 in, which Table 6.5 puts at a deficit of 0.05 in per inch of soil. His 1,300 ft pivot has a gross capacity of 6.4 gpm/ac, end tower speed of 9 ft/min at 100%, and DU = 0.85. What percent timer setting refills the low quarter of the 24 in root zone?",
    opts: ["About 15%", "About 18%", "About 30%", "About 21%"], a: 0,
    why: "SWD = 0.05 × 24 = 1.2 in. To put 1.2 in on the low quarter, apply 1.2/0.85 = 1.41 in gross. Cs = 0.0231 × 1,300 × 6.4/(9 × 1.41) = 15%. Setting for only 1.2 in gross gives about 18% and leaves the low quarter short, refilling only the top 12 in gives about 30%, and multiplying by DU instead of dividing gives about 21%.",
    eq: "13.7", calc: "eq-13.7", fig: null, table: "6.5" },
  { id: "x-008", ch: 4, sec: "4.6", page: 68, type: "scenario", level: 3,
    q: "A grower deficit irrigating sorghum says his checkbook still subtracts Kco × ETo = 1.1 × 0.30 = 0.33 in/d. The soil is at θv = 0.17, with field capacity 0.28 and wilting point 0.12, and the crop's critical fraction remaining is 0.50. About how much is the crop really using?",
    opts: ["About 0.33 in/d, ET is not reduced until wilting point", "About 0.10 in/d, because only 31% of available water is left", "About 0.30 in/d, because stressed crops use ETo", "About 0.21 in/d, because Ks is about 0.63"], a: 3,
    why: "Fraction remaining fr = (0.17 − 0.12)/(0.28 − 0.12) = 0.31, which is below the critical 0.50. Ks = fr/frc = 0.31/0.50 = 0.63, so ET = 0.63 × 1.1 × 0.30 = 0.21 in/d. The checkbook overstates use by about 0.12 in/d, so the field is wetter than it shows. Multiplying ET by fr itself (0.10 in/d) is a common slip.",
    eq: "4.10", calc: "eq-4.10-p68", fig: null, table: null },
  { id: "x-009", ch: 4, sec: "4.6", page: 71, type: "calc", level: 3,
    q: "Field corn (Table 4.3: Kcp = 1.15, midseason from 0.41 to 0.71 of the season) has accumulated 1,350 of the 2,700 GDD it needs. ETo is 0.30 in/d. The soil has AD = 2.4 in and SWD = 1.1 in. How many days until the latest irrigation date?",
    opts: ["About 4.3 days", "About 8.0 days", "About 6.0 days", "About 3.8 days"], a: 3,
    why: "Fs = 1,350/2,700 = 0.50 (Eq. 4.13), which is in the midseason stage, so Kco = 1.15. ET = 1.15 × 0.30 = 0.345 in/d and LD = (2.4 − 1.1)/0.345 = 3.8 days. Using ETo gives 4.3 days, and dividing AD alone by ETo gives 8.0 days.",
    eq: "6.10", calc: "eq-6.10-6.11", fig: null, table: "4.3" },
  { id: "x-010", ch: 13, sec: "13.5", page: 288, type: "scenario", level: 2,
    q: "A grower irrigates weekly. Last week crop ET was 0.27, 0.31, 0.29, 0.24, 0.30, 0.33 and 0.28 in, and 0.45 in of effective rain fell. His 1,300 ft pivot has ELQ = 85%, gross capacity 6.2 gpm/ac and an end tower speed of 9 ft/min at 100%. What timer setting puts the week's need back?",
    opts: ["About 9%", "About 11%", "About 13%", "About 15%"], a: 1,
    why: "Net need = 2.02 − 0.45 = 1.57 in (Eq. 6.26). Gross = 1.57/0.85 = 1.85 in. Cs = 0.0231 × 1,300 × 6.2/(9 × 1.85) = 11%. Applying only the net 1.57 in gives about 13%, and ignoring the rain (2.02/0.85 = 2.38 in) gives about 9%, which means a slower pivot and more water.",
    eq: "13.7", calc: "eq-13.7", fig: null, table: null },
  { id: "x-011", ch: 13, sec: "13.5", page: 288, type: "scenario", level: 3,
    q: "A grower runs his 1,300 ft pivot at a 30% timer to \"keep the top wet\". Gross capacity is 6.2 gpm/ac, end tower speed is 9 ft/min at 100%, and DU is 0.85. His SWD before each pass is about 1.0 in. What is he putting on and what do you advise?",
    opts: ["About 2.3 in gross, so he is overwatering and leaching", "About 0.21 in gross, so he is barely wetting the canopy", "About 1.0 in gross, which exactly matches the deficit", "About 0.69 in gross, so the low quarter gets 0.59 in and the deficit is never refilled"], a: 3,
    why: "Depth at 100% is 0.0231 × 1,300 × 6.2/(9 × 100) = 0.207 in, so at 30% it is 0.207/0.30 = 0.69 in. The low quarter gets 0.85 × 0.69 = 0.59 in, well short of the 1.0 in deficit, so the root zone keeps drying while the surface stays wet. Multiplying instead of dividing by the timer fraction is the usual slip that gives 0.21 in.",
    eq: "13.7", calc: "eq-13.7-inv", fig: null, table: null },
  { id: "x-012", ch: 5, sec: "5.3", page: 88, type: "scenario", level: 2,
    q: "A pivot's catch-can test shows DU = 0.75. The grower applies 0.9 in when SWD is 1.0 in and says, \"Nothing runs off, so I'm 100% efficient.\" What do you tell him?",
    opts: ["ELQ is 75%, but the real problem is the low quarter gets only 0.68 in against a 1.0 in deficit", "ELQ is 90%, because 0.9 of the 1.0 in deficit was replaced", "ELQ is 100%, because no water was lost to runoff or deep percolation", "ELQ is 68%, because the low quarter got 0.68 in"], a: 0,
    why: "dLQ = 0.75 × 0.9 = 0.675 in, and de is the smaller of dLQ and SWD, so de = 0.675 in. ELQ = 0.675/0.9 = 75%. High efficiency does not mean adequate: a quarter of the field is short about 0.3 in. Dividing by the deficit or reporting dLQ as a percent are common mix-ups.",
    eq: "5.11", calc: "eq-5.9-5.11", fig: null, table: null },
  { id: "x-013", ch: 5, sec: "5.3", page: 88, type: "scenario", level: 3,
    q: "A grower with a well-tuned pivot (DU = 0.85) puts on 1.6 in every time \"to be safe\", but his SWD before irrigating is usually 1.0 in. What is his ELQ, and what gross depth would refill the low quarter without excess?",
    opts: ["About 85%, and 1.6 in is about right", "About 63%, and about 1.2 in would do it", "About 63%, and 1.0 in would do it", "About 54%, and about 1.4 in would do it"], a: 1,
    why: "dLQ = 0.85 × 1.6 = 1.36 in, more than the 1.0 in deficit, so de = 1.0 in and ELQ = 1.0/1.6 = 62.5%. To refill the low quarter exactly, apply SWD/DU = 1.0/0.85 = 1.18 in. Applying just 1.0 in leaves the low quarter short, and quoting DU as ELQ ignores the deep percolation.",
    eq: "5.11", calc: "eq-5.9-5.11", fig: null, table: null },
  { id: "x-014", ch: 5, sec: "5.3", page: 91, type: "calc", level: 3,
    q: "A pivot test gives CU = 86% and DU = 0.78. Each irrigation infiltrates 1.4 in on average when SWD is 1.0 in, and leachate carries 25 ppm nitrate-N. About how much nitrate-N leaves the root zone per irrigation?",
    opts: ["About 2.0 lb/ac", "About 2.3 lb/ac", "About 2.5 lb/ac", "About 10.9 lb/ac"], a: 2,
    why: "Table 5.1 gives F1 = 0.75 at CU 86, so Vdp1 = 1.4 × (1 − 0.75) = 0.35 in. dLQ = 0.78 × 1.4 = 1.09 in, so Vdp2 = 0.95 × (1.09 − 1.0) = 0.09 in. Total dp = 0.44 in and Cl = 0.226 × 25 × 0.44 = 2.5 lb/ac. Leaving out the excess term gives 2.0 lb/ac, and dropping the 0.226 factor gives 10.9.",
    eq: "5.18", calc: "leaching-procedure", fig: null, table: "5.1" },
  { id: "x-015", ch: 5, sec: "5.6", page: 97, type: "scenario", level: 2,
    q: "A grower's well makes 750 gpm on a 125 acre pivot with ELQ = 85%. In July, ETo runs 0.28 in/d and his corn Kc is 1.2. He asks, \"Can the pivot keep up?\" What do you tell him?",
    opts: ["Yes, it supplies about 0.32 in/d, which beats ETo", "Yes, 750 gpm is 6 gpm/ac, which is above the 5 gpm/ac rule", "No, it nets only about 0.24 in/d, so he must add a second well", "No, it nets about 0.27 in/d against 0.34 in/d of use, so start July with a full profile"], a: 3,
    why: "Gross capacity = 750/125 = 6.0 gpm/ac = 750/(448.8 × 125) × 24 = 0.32 in/d. Net = 0.85 × 0.32 = 0.27 in/d. Crop ET = 1.2 × 0.28 = 0.34 in/d, so the soil must make up about 0.07 in/d during the peak. Comparing gross capacity to ETo hides both the efficiency loss and the Kc.",
    eq: "5.20", calc: "cn-from-flow", fig: null, table: null },
  { id: "x-016", ch: 13, sec: "13.5", page: 292, type: "scenario", level: 3,
    q: "A grower's 1,300 ft pivot on silt loam has 6.0 gpm/ac gross capacity and spray heads with a 40 ft wetted diameter. Field slope gives about 0.3 in of surface storage. He applies 1.0 in per pass and sees runoff near the end. Using Table 13.8, what do you recommend?",
    opts: ["Drop to 0.8 in per pass, which needs only about 33 ft of wetted diameter", "Raise to 1.2 in per pass so he passes less often", "Keep 1.0 in, because 40 ft is wider than the 33 ft needed", "Keep 1.0 in, but slow the pivot to soak in better"], a: 0,
    why: "For silt loam at 6.0 gpm/ac, 1.0 in and 0.3 in storage, Table 13.8 calls for at least 50 ft of wetted diameter, so 40 ft runs off. At 0.8 in the minimum falls to 33 ft, which his sprays meet. A larger depth (1.2 in needs 67 ft) or a slower pivot (which applies more per pass) makes runoff worse.",
    eq: null, calc: "tab-13.8", fig: null, table: "13.8" },
  { id: "x-017", ch: 13, sec: "13.2", page: 279, type: "calc", level: 3,
    q: "A 1,300 ft pivot with gross capacity 6.5 gpm/ac has sprinklers spaced 9 ft apart near the end. If the end sprinkler runs at 20 psi with a discharge coefficient of 0.96, about what nozzle diameter does it need?",
    opts: ["About 13/64 in", "About 19/64 in", "About 24/64 in", "About 16/64 in"], a: 1,
    why: "q = 2π R S Cg/43,560 = 2π × 1,300 × 9 × 6.5/43,560 = 11.0 gpm (Eq. 13.1). From Eq. 11.1, D = √[q/(29.82 × 0.96 × √20)] = 0.293 in, or about 18.7/64, so about 19/64 in. Smaller nozzles would starve the outer ring, which carries the most area per foot of lateral.",
    eq: "13.1", calc: "eq-13.1", fig: null, table: null },
  { id: "x-018", ch: 13, sec: "13.5", page: 288, type: "scenario", level: 3,
    q: "A grower set his 1,280 ft pivot (gross capacity 6.0 gpm/ac, 8 ft/min at 100%) to a 40% timer for light, frequent passes. ELQ is 85% and crop ET is 0.32 in/d. He asks if this keeps up. What do you say?",
    opts: ["Yes, each pass puts on 0.55 in and the crop uses only 0.32 in/d", "Yes, light passes are always more efficient, so the net is the full 0.55 in", "No, each 42 hr pass nets about 0.47 in while the crop uses about 0.56 in", "No, each pass nets only about 0.19 in"], a: 2,
    why: "At 40%, depth = 0.0231 × 1,280 × 6.0/(8 × 40) = 0.55 in gross and the revolution takes 2π × 1,280/(8 × 0.40)/60 = 42 hr. Net is 0.85 × 0.55 = 0.47 in, but ET over 42 hr is 0.32 × 42/24 = 0.56 in. The deficit grows every pass, and comparing depth per pass to ET per day ignores how long the pass takes.",
    eq: "13.7", calc: "eq-13.7-inv", fig: null, table: null },
  { id: "x-019", ch: 5, sec: "5.3", page: 90, type: "calc", level: 2,
    q: "An orchard solid set has 4.5 gpm sprinklers on a 30 ft × 40 ft spacing. An audit gives a scheduling coefficient of 1.25. The trees need 1.2 in net. How long should each set run?",
    opts: ["About 3.3 hr", "About 2.7 hr", "About 4.2 hr", "About 5.2 hr"], a: 2,
    why: "Application rate = 96.3 × 4.5/(30 × 40) = 0.36 in/hr (Eq. 3.5). Base run time = 1.2/0.36 = 3.3 hr, and multiplying by SC = 1.25 gives 4.2 hr. Stopping at 3.3 hr leaves the driest areas short, and dividing by SC (2.7 hr) runs the wrong way.",
    eq: "5.13", calc: "eq-5.13", fig: null, table: null },
  { id: "x-020", ch: 5, sec: "5.3", page: 88, type: "scenario", level: 2,
    q: "A grower reads his flow meter at 15,302,000 gal before a pivot pass and 18,840,000 gal after, on 125 acres. His catch-can DU is 0.85 and SWD before the pass was 1.0 in. Was the pass enough?",
    opts: ["Yes, about 1.04 in went on, which beats the 1.0 in deficit everywhere", "Not quite, about 1.04 in went on and the low quarter got about 0.89 in", "No, only about 0.39 in went on", "Yes, about 1.30 in went on, so even the low quarter is full"], a: 1,
    why: "Volume = 3,538,000 gal, or 3,538,000/27,154 = 130.3 ac-in, so depth = 130.3/125 = 1.04 in. The low quarter gets 0.85 × 1.04 = 0.89 in, about 0.11 in short of the deficit, so ELQ is 85% but adequacy is not. A depth that matches the average deficit always leaves the low quarter short.",
    eq: "5.11", calc: "meter-depth", fig: null, table: null },
  { id: "x-021", ch: 7, sec: "7.7", page: 140, type: "scenario", level: 3,
    q: "A corn grower (threshold T = 1.7 dS/m) irrigates with well water at EC 1.8 dS/m and gets no useful rain in summer. Peak crop ET is 0.32 in/d and his pivot ELQ is 85%. If he has to supply the leaching requirement during the peak period, about what gross capacity does he need?",
    opts: ["About 8.7 gpm/ac", "About 7.1 gpm/ac", "About 6.0 gpm/ac", "About 8.4 gpm/ac"], a: 0,
    why: "Figure 7.11 gives Lr of about 0.18 for ECa 1.8 and T 1.7. The infiltrated depth must be ET/(1 − Lr) = 0.32/0.82 = 0.39 in/d, and gross = 0.39/0.85 = 0.46 in/d, or 0.46 × 18.86 = 8.7 gpm/ac. Ignoring leaching gives 7.1 gpm/ac, ignoring efficiency too gives 6.0, and multiplying ET by (1 + Lr) instead of dividing by (1 − Lr) gives 8.4.",
    eq: "7.8", calc: "fig-7.11", fig: "7.11", table: null },
  { id: "x-022", ch: 7, sec: "7.7", page: 139, type: "calc", level: 2,
    q: "Applied water has EC 2.0 dS/m and the crop tolerates drainage water up to 10 dS/m. Seasonal crop ET is 24 in with no rain, all applied water infiltrates, and the farm ditch delivers 80% of what is diverted at the headgate. How much must be diverted?",
    opts: ["About 30.0 in", "About 37.5 in", "About 36.0 in", "About 28.8 in"], a: 1,
    why: "Lr = ECa/ECd = 2.0/10 = 0.20 (Eq. 7.8). Infiltrated depth dt = 24/(1 − 0.20) = 30 in, of which 6 in drains. With 80% conveyance efficiency (Eq. 5.19), the diversion is 30/0.8 = 37.5 in. Using 24 × 1.2 = 28.8 in understates the leaching, and stopping at 30 in forgets the ditch loss.",
    eq: "7.8", calc: "eq-7.8", fig: null, table: null },
  { id: "x-023", ch: 7, sec: "7.7", page: 139, type: "calc", level: 3,
    q: "A field receives 20 in of irrigation water at 2.4 dS/m and 6 in of effective rain (about 0 dS/m). The crop can tolerate drainage water up to 9 dS/m. What is the leaching requirement?",
    opts: ["About 0.27", "About 0.13", "About 0.79", "About 0.21"], a: 3,
    why: "The weighted salinity of applied water is Ca = (2.4 × 20 + 0 × 6)/(20 + 6) = 1.85 dS/m (Eq. 7.7). Lr = 1.85/9 = 0.21 (Eq. 7.8). Ignoring the rain gives 2.4/9 = 0.27, a simple average of 2.4 and 0 gives 0.13, and 0.79 is 1 − Lr.",
    eq: "7.7", calc: "eq-7.7", fig: null, table: null },
  { id: "x-024", ch: 7, sec: "7.2", page: 134, type: "scenario", level: 3,
    q: "A grower's meter read 4,210,000 gal before an irrigation and 7,468,000 gal after, on 40 acres. His well water tests 1.2 dS/m. He asks how much salt that one irrigation brought onto the field.",
    opts: ["About 0.26 tons", "About 16 tons", "About 10 tons", "About 21 tons"], a: 2,
    why: "Volume = 3,258,000 gal = 120 ac-in, so depth = 3.0 in on 40 ac. TDS = 640 × 1.2 = 768 mg/L (Eq. 7.2). Salt = 0.226 × 768 × 3.0 = 521 lb/ac, and 521 × 40 = 20,800 lb, or about 10.4 tons. 0.26 tons is the per acre figure, 16 tons uses 1,000 × EC for TDS, and 21 tons divides pounds by 1,000.",
    eq: "7.2", calc: "salt-applied", fig: null, table: null },
  { id: "x-025", ch: 7, sec: "7.8", page: 141, type: "scenario", level: 3,
    q: "A grower wants to bring a 20 acre field from ECe 12 to ECe 3 dS/m through a 3 ft root zone. He will sprinkle intermittently from a 900 gpm well, running around the clock. About how long will reclamation take?",
    opts: ["About 18 days of pumping", "About 2 days of pumping", "About 6 days of pumping", "About 1.5 days of pumping"], a: 2,
    why: "For intermittent sprinkling K = 0.1, so dL/ds = K/(Cf/Co) = 0.1/(3/12) = 0.4 and dL = 0.4 × 3 ft = 1.2 ft = 14.4 in (Eq. 7.10). On 20 ac that is 288 ac-in, and 900 gpm is about 2.0 ac-in/hr, so 144 hr or 6 days. Continuous ponding on a clay loam (K = 0.3) would take three times the water, about 18 days, leaching only the top foot gives 2 days, and leaving out the concentration ratio gives 1.5 days.",
    eq: "7.10", calc: "eq-7.9-7.10", fig: null, table: null },
  { id: "x-026", ch: 7, sec: "7.5", page: 138, type: "scenario", level: 2,
    q: "A grower switched his pivot to a new well and now sees ponding and runoff where there was none. The water tests EC 0.5 dS/m with Na 12, Ca 2 and Mg 1 meq/L. What do you tell him?",
    opts: ["SAR is about 6.9, which is low, so look for worn nozzles instead", "EC is too high, so he needs to apply extra water for leaching", "SAR is about 4.0, which only matters for drip systems", "SAR is about 9.8 at low EC, a severe infiltration hazard, so consider gypsum and lighter passes"], a: 3,
    why: "SAR = Na/√[(Ca + Mg)/2] = 12/√1.5 = 9.8. Figure 7.10 puts SAR near 10 with EC 0.5 dS/m in the severe reduction zone, because low salt water with high sodium disperses the soil surface. Adding gypsum and cutting depth per pass (Chapter 13) attacks both sides. Forgetting to halve Ca + Mg gives 6.9, and more water would only make runoff worse.",
    eq: "7.4", calc: "eq-7.4-7.5", fig: "7.10", table: null },
  { id: "x-027", ch: 7, sec: "7.4", page: 135, type: "scenario", level: 3,
    q: "A grower's salty field tests ECe 4.0 dS/m. He is deciding between corn (T = 1.7 dS/m, S = 12%/dS/m) and alfalfa (T = 2.0 dS/m, S = 7.3%/dS/m) and asks which loses less yield. What do you tell him?",
    opts: ["Corn drops to about 85% and alfalfa to about 72%, so corn holds up better", "Both stay at 100%, because 4.0 is below the slope values", "Corn drops to about 52% and alfalfa to about 71%", "Corn drops to about 72% and alfalfa to about 85%, so alfalfa holds up better"], a: 3,
    why: "Yr = 100 − S(ECe − T). Corn: 100 − 12 × (4.0 − 1.7) = 72%. Alfalfa: 100 − 7.3 × (4.0 − 2.0) = 85%. Applying the slope to the full ECe instead of the excess over threshold gives 52% and 71%.",
    eq: "7.3", calc: "eq-7.3", fig: null, table: null },
  { id: "x-028", ch: 7, sec: "7.7", page: 140, type: "calc", level: 3,
    q: "Drip tomatoes (T = 2.5 dS/m) get water at EC 2.0 dS/m. Daily ET is 0.30 in, emitters are 12 in apart on laterals 60 in apart, each emitter runs at 0.24 gph, and there is no rain. Figure 7.11 gives Lr of about 0.15. How long should the daily set run to cover ET plus leaching?",
    opts: ["About 3.9 hr", "About 5.6 hr", "About 3.3 hr", "About 4.6 hr"], a: 3,
    why: "Infiltrated depth = ET/(1 − Lr) = 0.30/0.85 = 0.35 in, so dp = 0.05 in. Each emitter serves 1 ft × 5 ft = 5 ft², so the rate is 0.24 gph × 0.1337 ft³/gal ÷ 5 ft² × 12 in/ft = 0.077 in/hr. Run time = 0.35/0.077 = 4.6 hr. ET alone needs 3.9 hr, reading the 0.30 line of the figure gives 5.6 hr, and subtracting leaching gives 3.3 hr.",
    eq: "14.8", calc: "drip-runtime", fig: "7.11", table: null },
  { id: "x-029", ch: 7, sec: "7.7", page: 139, type: "scenario", level: 3,
    q: "A grower needs a leaching fraction of 0.15 and sets his average application to 1.18 in for every 1.0 in of ET. His pivot DU is 0.75. He says, \"The averages work out, so I'm leaching.\" What do you tell him?",
    opts: ["The low quarter gets only about 0.88 in per inch of ET, so it gets no leaching and salt will build there", "He is right, a 0.15 leaching fraction on average leaches every part of the field", "The low quarter gets about 1.18 in, so it is leached the same as the rest", "The low quarter gets about 1.57 in, so it is over leached"], a: 0,
    why: "dLQ = 0.75 × 1.18 = 0.88 in, which does not even meet the 1.0 in of ET, so nothing drains below the driest quarter. Salinity builds in those spots while the wet spots over leach. Improving uniformity, or sizing leaching from the low quarter depth, is the fix. Dividing by DU instead of multiplying gives 1.57 in.",
    eq: "7.6", calc: "eq-5.8", fig: null, table: null },
  { id: "x-030", ch: 14, sec: "14.5", page: 308, type: "scenario", level: 2,
    q: "A vegetable grower wants to convert to drip using a well that tests 1.5 dS/m. He asks whether the dissolved salts are a plugging concern. What do you tell him?",
    opts: ["TDS is about 1.5 ppm, so plugging from salts is minor", "TDS is about 2,400 ppm, a severe plugging potential, so drip will not work", "EC only affects crop yield, not emitter plugging", "TDS is about 960 ppm, a moderate plugging potential, so plan for filtration and treatment"], a: 3,
    why: "TDS = 640 × EC = 640 × 1.5 = 960 mg/L, about 960 ppm (Eq. 7.2). Table 14.2 rates salts of 500 to 2,000 ppm as a moderate plugging potential. Dissolved salts can precipitate at the emitter when water evaporates between irrigations, so filtering alone will not fix it. Multiplying by 1,600 instead of 640 gives a false severe rating.",
    eq: "7.2", calc: "eq-7.2", fig: null, table: "14.2" },
  { id: "x-031", ch: 8, sec: "8.6", page: 164, type: "calc", level: 3,
    q: "A well has a static level of 120 ft. On test it pumped 900 gpm with a pumping level of 150 ft. The grower wants 1,000 gpm at 45 psi at the discharge. With a 75% efficient pump, what brake horsepower is needed?",
    opts: ["About 67 hp", "About 75 hp", "About 87 hp", "About 49 hp"], a: 2,
    why: "Specific capacity = 900/30 = 30 gpm/ft, so at 1,000 gpm drawdown is 33.3 ft and the pumping level is 153.3 ft (Eq. 9.3). TDH = 153.3 + 2.31 × 45 = 257 ft. whp = 1,000 × 257/3,960 = 65 hp, and bhp = 65/0.75 = 87 hp. Dropping the 2.31 gives 67 hp, using the static level gives 75 hp, and multiplying by efficiency gives 49 hp.",
    eq: "8.19", calc: "eq-8.17-8.19", fig: null, table: null },
  { id: "x-032", ch: 8, sec: "8.7", page: 167, type: "calc", level: 3,
    q: "An electric pump lifts water from a pumping level of 153 ft and discharges at 45 psi. The plant has a performance rating of 0.85 and power costs $0.11/kWh. What does it cost to pump one acre-inch?",
    opts: ["About $3.66", "About $5.06", "About $4.30", "About $2.56"], a: 2,
    why: "TDH = 153 + 2.31 × 45 = 257 ft. Energy at the Nebraska criteria is 0.1157 × 257/0.885 = 33.6 kWh per ac-in, and dividing by PR 0.85 gives 39.1 kWh. Cost = 39.1 × $0.11 = $4.30 per ac-in. Ignoring PR gives $3.66, dividing by PR twice gives $5.06, and leaving out the pressure head gives about $2.56.",
    eq: "8.22", calc: "eq-8.22", fig: null, table: null },
  { id: "x-033", ch: 8, sec: "8.7", page: 167, type: "scenario", level: 3,
    q: "A grower pumps from a 150 ft lift and runs his pivot at 55 psi at the pump. A dealer offers to renozzle the pivot so the pump only needs 30 psi at the same flow. He pumps 700 ac-in a year with an electric plant at PR 0.90 and $0.12/kWh. About what will he save each year?",
    opts: ["About $300", "About $3,300", "About $2,600", "About $700"], a: 3,
    why: "TDH drops from 150 + 2.31 × 55 = 277 ft to 150 + 2.31 × 30 = 219 ft. Cost per ac-in falls from about $4.77 to $3.78, a saving of about $0.99 per ac-in, or about $700 on 700 ac-in (Eq. 8.22). Forgetting the 2.31 gives about $300, and $3,300 and $2,600 are the total yearly bills before and after.",
    eq: "8.22", calc: "eq-8.22", fig: null, table: null },
  { id: "x-034", ch: 8, sec: "8.3", page: 152, type: "scenario", level: 3,
    q: "A grower will pipe 900 gpm through 2,640 ft of 8 in PVC (inside diameter 7.92 in, C = 150) to a pivot that sits 25 ft higher than the pump. The pivot needs 35 psi at its inlet. What pressure should the pump deliver?",
    opts: ["About 60 psi", "About 49 psi", "About 46 psi", "About 74 psi"], a: 0,
    why: "Hazen-Williams gives about 0.53 psi per 100 ft, or 14.1 psi over 2,640 ft (Eq. 8.11). The 25 ft rise costs 25/2.31 = 10.8 psi. Pump pressure = 35 + 14.1 + 10.8 = 60 psi. Leaving out the rise gives 49 psi, leaving out friction gives 46 psi, and adding the 25 ft as if it were psi gives 74 psi.",
    eq: "8.11", calc: "eq-8.11", fig: null, table: null },
  { id: "x-035", ch: 9, sec: "9.4", page: 179, type: "scenario", level: 3,
    q: "A grower wants to push his well from 700 to 950 gpm so his 130 acre pivot reaches 7.3 gpm/ac. Static level is 95 ft, the pumping level at 700 gpm is 140 ft, and the pump bowls are set at 150 ft. What do you tell him?",
    opts: ["Yes, the pumping level would stay near 140 ft because drawdown does not change with flow", "No, at 950 gpm the pumping level would fall to about 156 ft, below the bowls", "Yes, drawdown would only rise to about 49 ft, a pumping level of about 144 ft", "No, the pumping level would fall to about 178 ft because drawdown goes with flow squared"], a: 1,
    why: "Specific capacity = 700/45 = 15.6 gpm/ft (Eq. 9.2). At 950 gpm, drawdown = 950/15.6 = 61 ft and the pumping level is 95 + 61 = 156 ft, below the 150 ft bowls (Eq. 9.3). The pump would break suction and cavitate. Eq. 9.3 assumes drawdown is proportional to flow, not to its square.",
    eq: "9.3", calc: "well-test", fig: null, table: null },
  { id: "x-036", ch: 9, sec: "9.4", page: 179, type: "calc", level: 2,
    q: "Over a dry summer a well's pumping level drops 15 ft, raising TDH from 200 to 215 ft. The diesel plant meets the Nebraska criteria (PR 1.0), diesel is $3.50/gal, and the grower pumps 900 ac-in. About how much more will the season cost?",
    opts: ["About $6,190", "About $5,760", "About $120", "About $430"], a: 3,
    why: "Fuel per ac-in is 0.1157 × TDH/12.5 gallons: 1.83 gal at 200 ft and 1.97 gal at 215 ft (Eq. 8.22). The extra 0.137 gal × $3.50 = $0.48 per ac-in, or about $430 over 900 ac-in. $6,190 and $5,760 are the whole season's fuel bills, and 120 is the extra gallons, not dollars.",
    eq: "8.22", calc: "eq-8.22", fig: null, table: null },
  { id: "x-037", ch: 8, sec: "8.7", page: 166, type: "scenario", level: 2,
    q: "A grower's diesel well pumps 800 gpm from a pumping level of 140 ft and the discharge gauge reads 40 psi. A fuel check shows 5.5 gal/hr. He asks if his pumping plant is doing all right. What do you tell him?",
    opts: ["PR is about 1.0, so it meets the Nebraska criteria", "PR is about 1.46, so it beats the criteria", "PR is about 0.53, so the pump must be replaced now", "PR is about 0.68, so a tune-up or repair is likely worth it"], a: 3,
    why: "TDH = 140 + 2.31 × 40 = 232 ft and whp = 800 × 232/3,960 = 47 hp. Performance = 47/5.5 = 8.5 whp-hr/gal against the 12.5 criteria, so PR = 0.68 (Eq. 8.20). He uses about 46% more fuel than a plant at the criteria. Inverting the ratio gives 1.46, and forgetting the 2.31 gives 0.53.",
    eq: "8.20", calc: "pump-eval", fig: null, table: "8.6" },
  { id: "x-038", ch: 8, sec: "8.6", page: 164, type: "calc", level: 2,
    q: "The sweep hand on a 1,000 gal per revolution totalizer makes 10 turns in 690 seconds. TDH is 240 ft and the pump is 72% efficient. What brake horsepower is the pump drawing?",
    opts: ["About 53 hp", "About 73 hp", "About 38 hp", "About 7.3 hp"], a: 1,
    why: "Flow = 10 × 1,000 gal/(690/60 min) = 870 gpm (Section 3.3). whp = 870 × 240/3,960 = 52.7 hp and bhp = 52.7/0.72 = 73 hp. 53 hp is the water horsepower, 38 hp multiplies by efficiency, and 7.3 hp reads the dial as 100 gal per turn.",
    eq: "8.19", calc: "eq-8.17-8.19", fig: null, table: null },
  { id: "x-039", ch: 8, sec: "8.5", page: 159, type: "calc", level: 2,
    q: "Pressure at the end of a pivot is 25 psi, but the end gun needs 55 psi at 110 gpm. What brake horsepower does the booster pump need if it is 60% efficient?",
    opts: ["About 1.9 hp", "About 5.9 hp", "About 3.2 hp", "About 1.4 hp"], a: 2,
    why: "Booster TDH = 2.31 × (55 − 25) = 69.3 ft (Eq. 8.14). whp = 110 × 69.3/3,960 = 1.9 hp and bhp = 1.9/0.60 = 3.2 hp. 1.9 hp is the water horsepower, sizing on the full 55 psi gives 5.9 hp, and leaving out the 2.31 gives 1.4 hp.",
    eq: "8.14", calc: "eq-8.14", fig: null, table: null },
  { id: "x-040", ch: 8, sec: "8.5", page: 163, type: "scenario", level: 3,
    q: "An engine pump delivers 1,000 gpm at 280 ft TDH at 1,770 rpm. To ease drawdown the grower wants to slow the engine 10%, to 1,593 rpm. His pivot system needs about 250 ft of TDH. What happens?",
    opts: ["Flow falls to about 900 gpm and head stays at 280 ft, so nothing else changes", "Flow falls to about 900 gpm but head falls to about 227 ft, so pivot pressure drops about 10 psi", "Flow falls to about 810 gpm and head to about 252 ft, so the pivot still gets pressure", "Flow stays at 1,000 gpm and only fuel use drops by about 27%"], a: 1,
    why: "By the affinity laws (Eq. 8.15), flow goes with speed (0.9 × 1,000 = 900 gpm), head with speed squared (0.81 × 280 = 227 ft), and power with speed cubed (about 73%). The pump can no longer make the 250 ft the system needs, so the shortfall of about 23 ft is about 10 psi at the pivot. Slowing a pump to cut flow also cuts pressure, so the nozzles or the well need a different fix.",
    eq: "8.15", calc: "eq-8.15", fig: null, table: null },
  { id: "x-041", ch: 14, sec: "14.7", page: 317, type: "calc", level: 2,
    q: "Drip lettuce has emitters 12 in apart on laterals 60 in apart, each at 0.24 gph. ETo is 0.30 in/d and the crop coefficient is 0.95. Ignoring rain and leaching, how long should the daily set run?",
    opts: ["About 3.9 hr", "About 3.7 hr", "About 0.74 hr", "About 18.5 hr"], a: 1,
    why: "Crop ET = 0.95 × 0.30 = 0.285 in. Each emitter wets 5 ft², so the rate is 0.24 × 0.1337 ft³/gal ÷ 5 ft² × 12 = 0.077 in/hr. Time = 0.285/0.077 = 3.7 hr. Using ETo gives 3.9 hr, using 1 ft² per emitter gives 0.74 hr, and multiplying by the area instead of dividing gives 18.5 hr.",
    eq: "14.9", calc: "drip-runtime", fig: null, table: null },
  { id: "x-042", ch: 14, sec: "14.6", page: 312, type: "scenario", level: 3,
    q: "A drip grower runs 1.35 hr a day to apply 0.25 in. His emitters follow q = 0.12 h^0.5 (q in gph, h in ft) and were designed for 10 psi. A clogged filter has dropped emitter pressure to 7 psi. What is happening and what should he do?",
    opts: ["Flow is down 30%, the same as the pressure, so he needs about 1.9 hr", "Flow is unchanged, because emitters with x = 0.5 are pressure compensating", "Flow is down about 8%, so he needs about 1.45 hr", "Flow is down about 16%, so clean the filter, or he needs about 1.6 hr to apply the same depth"], a: 3,
    why: "10 psi = 23.1 ft and 7 psi = 16.2 ft (Eq. 8.3). q = 0.12 × 23.1^0.5 = 0.58 gph at design and 0.12 × 16.2^0.5 = 0.48 gph now, a 16% drop (Eq. 14.3). Run time to apply 0.25 in rises from 1.35 to about 1.6 hr. The better fix is to clean the filter when the pressure drop across it reaches 3 to 5 psi, since low pressure also hurts uniformity.",
    eq: "14.3", calc: "eq-14.3", fig: null, table: null },
  { id: "x-043", ch: 15, sec: "15.4", page: 332, type: "scenario", level: 3,
    q: "A grower will fertigate a 20 acre drip zone with 15 lb N/ac of UAN 32 (3.54 lb N/gal). The zone runs 4 hr. He needs 30 min at the start to fill and pressurize the system and a 30 min flush at the end. His injection pump tops out at 30 gph. What injection rate and dial setting do you give him?",
    opts: ["About 21 gph, a dial setting of about 71%", "About 28 gph, a dial setting of about 94%", "About 85 gph, beyond the pump's range", "About 42 gph, beyond the pump's range"], a: 1,
    why: "Product per acre = 15/3.54 = 4.24 gal/ac, so 84.7 gal for 20 ac. Injection time is 4 − 0.5 − 0.5 = 3 hr, so qi = 84.7/3 = 28 gph (Eq. 15.1) and the dial is 28/30 = 94%. Spreading it over the full 4 hr (21 gph) leaves fertilizer in the lines at shutoff, and 85 gph would inject it all in one hour.",
    eq: "15.1", calc: "injection-plan", fig: null, table: null },
  { id: "x-044", ch: 14, sec: "14.6", page: 315, type: "calc", level: 2,
    q: "A drip evaluation catches these emitter flows (gph): 0.98, 1.04, 0.86, 1.01, 0.95, 1.07, 0.79, 0.99, 1.02, 0.91, 1.05, 0.93, 0.97, 1.00, 0.88, 1.03. If the crop needs 0.25 in/d net, what gross depth should the controller apply?",
    opts: ["About 0.22 in/d", "About 0.28 in/d", "About 0.25 in/d", "About 0.31 in/d"], a: 1,
    why: "Mean flow = 0.968 gph and the lowest 4 average 0.86 gph, so field DU = 0.86/0.968 = 0.89 (Eq. 14.6). Gross = 0.25/0.89 = 0.28 in/d, the same scheduling logic as Chapter 5. Multiplying by DU gives 0.22, ignoring uniformity gives 0.25, and using the single lowest emitter (0.79/0.968 = 0.82) gives 0.31.",
    eq: "14.6", calc: "eq-14.6", fig: null, table: null },
  { id: "x-045", ch: 14, sec: "14.7", page: 317, type: "calc", level: 2,
    q: "An orchard block uses 0.20 in/d of ET, and the grower adds 0.02 in/d for deep percolation. He wants to apply each day's water in 6 hr with 1.0 gph emitters. About how many emitters does each acre need?",
    opts: ["About 900", "About 6,000", "About 1,000", "About 170"], a: 2,
    why: "Gross depth = 0.20 + 0.02 = 0.22 in (Eq. 14.8). On one acre that is 0.22/12 × 43,560 ft³ × 7.48 gal/ft³ = 5,970 gal. In 6 hr at 1.0 gph each emitter gives 6 gal, so n = 5,970/6 = about 1,000 emitters (Eq. 14.9), or one per 44 ft². Leaving out the 0.02 in gives about 900, forgetting the 6 hr gives about 6,000, and dividing by 6 twice gives about 170.",
    eq: "14.9", calc: "eq-14.9", fig: null, table: null },
  { id: "x-046", ch: 15, sec: "15.4", page: 332, type: "scenario", level: 3,
    q: "A grower wants to chemigate 2 pt/ac on his 125 acre pivot (1,300 ft, gross capacity 6.2 gpm/ac, 9 ft/min at 100%) at a 50% timer setting. What injection rate should he set?",
    opts: ["About 10.4 pt/hr", "About 8.3 pt/hr", "About 16.5 pt/hr", "About 4.1 pt/hr"], a: 1,
    why: "At 50% one revolution takes 2π × 1,300/(9 × 0.50)/60 = 30.3 hr (Eq. 13.7). The pivot covers 125/30.3 = 4.13 ac/hr, so qi = 2 × 4.13 = 8.3 pt/hr (Eq. 15.2). Assuming a 24 hr revolution gives 10.4 pt/hr, using the 100% revolution time gives 16.5 pt/hr, and 4.1 is the coverage rate in ac/hr.",
    eq: "15.2", calc: "eq-15.2", fig: null, table: null },
  { id: "x-047", ch: 15, sec: "15.4", page: 335, type: "calc", level: 3,
    q: "A drip zone is fed by 800 ft of mainline (ID 5.9 in) at 300 gpm, a 300 ft manifold (ID 3.1 in) with laterals every 5 ft taking 2.5 gpm each, and 300 ft laterals (ID 0.6 in) with 0.24 gph emitters every 1 ft. After injection stops, about how long must water keep running to clear the chemical?",
    opts: ["About 4 min", "About 23 min", "About 31 min", "About 8 min"], a: 2,
    why: "Mainline: 0.0408 × 5.9² × 800/300 = 3.8 min (Eq. 15.3). Manifold by Eq. 15.4: about 3.7 min. Laterals by Eq. 15.4: about 23 min, because emitter flows are tiny. Total is about 31 min. Counting only the mainline gives 4 min, only the laterals gives 23, and the mainline plus manifold gives 8.",
    eq: "15.4", calc: "flush-total", fig: null, table: null },
  { id: "x-048", ch: 14, sec: "14.6", page: 315, type: "scenario", level: 3,
    q: "A grower is laying drip laterals across a 6 ft elevation change. Emitters have x = 0.5 and v = 0.05, the average head is 23.1 ft (10 psi) and lateral friction loss is 8 ft. He asks whether to feed the laterals from the low end or the high end. What do you tell him?",
    opts: ["Feed from the low end, design DU is about 90% uphill versus about 59% downhill", "It makes no difference, emitter exponent sets DU, not elevation", "Feed from the high end, but DU is only about 59% either way", "Feed from the high end, design DU is about 90% downhill versus about 59% uphill"], a: 3,
    why: "Running downhill, the 6 ft gain offsets most of the 8 ft friction loss, so the minimum head is 23.1 − 8 + 6 = 21.1 ft and design DU is about 90% (Eq. 14.7). Running uphill, the minimum head is 23.1 − 8 − 6 = 9.1 ft and DU falls to about 59%. With a non compensating emitter (x = 0.5), elevation and friction set the pressure variation, so lay laterals downhill on gentle slopes.",
    eq: "14.7", calc: "design-du", fig: null, table: null },
  { id: "x-049", ch: 15, sec: "15.4", page: 332, type: "scenario", level: 2,
    q: "A grower needs 12 gph from an injection pump rated 20 gph at full dial, so he set it at 60%. A calibration check catches 1,700 mL in 2 minutes. What do you tell him?",
    opts: ["It is putting out about 13.5 gph, so turn the dial down to about 53% and recheck", "It is putting out about 850 gph, so the pump is far oversized", "It is putting out about 12 gph, so the setting is right", "It is putting out about 10.6 gph, so turn the dial up to about 68%"], a: 0,
    why: "1,700 mL/2 min = 850 mL/min. 850 × 60/3,785 = 13.5 gph, about 12% high. If output is proportional to the dial, 60% × 12/13.5 = 53%. Always recheck with a timed catch (Section 3.3 logic), because pumps are not perfectly linear. Reading 850 mL/min as gph is a unit slip.",
    eq: "15.1", calc: "pump-calibration", fig: null, table: null },
  { id: "x-050", ch: 14, sec: "14.7", page: 317, type: "calc", level: 2,
    q: "A drip block has 0.5 gph emitters every 18 in on laterals 60 in apart. Over the last 3 days crop ET totaled 0.84 in and 0.30 in of effective rain fell. What run time replaces the net use?",
    opts: ["About 5.0 hr", "About 7.9 hr", "About 3.4 hr", "About 2.2 hr"], a: 0,
    why: "Gross depth = 0.84 − 0.30 = 0.54 in (Eq. 14.8). Each emitter serves 1.5 × 5 = 7.5 ft², so the rate is 0.5 × 0.1337 ÷ 7.5 × 12 = 0.107 in/hr. Time = 0.54/0.107 = 5.0 hr. Ignoring the rain gives 7.9 hr, using a 12 in emitter spacing gives 3.4 hr, and subtracting the rain twice gives 2.2 hr.",
    eq: "14.8", calc: "drip-runtime", fig: null, table: null },
  { id: "x-051", ch: 10, sec: "10.5", page: 197, type: "scenario", level: 3,
    q: "A furrow grower on silt loam with a closed tailwater return (Rt = 0.85) changes sets every 12 hr. He has 900 gpm, 30 in furrows 1,300 ft long on 0.25% slope, and SWD is usually 3.0 in. To hit the cutoff ratio of 0.40 he cuts from 60 to 42 furrows per set. What will his ELQ be, and what else must change?",
    opts: ["Only about 54%, because the low quarter gets about 4.7 in against a 3.0 in deficit, so he must also shorten the set", "About 85%, the peak of the medium soil curve, so nothing else needs to change", "About 39%, because 3.0 in of 7.6 in applied is stored, so he should drop the return system", "Not workable, because 21 gpm per furrow is erosive on a 0.25% slope"], a: 0,
    why: "At 42 furrows, qs = 900/42 = 21 gpm, below the 40 gpm nonerosive limit (Eq. 10.10). dg = 1,155 × 900 × 12/(42 × 30 × 1,300) = 7.6 in and Table 10.3 gives dLQ = 0.62 × 7.6 = 4.7 in, more than the 3.0 in SWD. ELQ = 3.0/(7.6 − 7.6 × 0.32 × 0.85) = 54% (Eq. 10.6). As in Example 10.5, the set time must also drop so that dLQ fits the deficit.",
    eq: "10.12", calc: "proc-furrow-set", fig: null, table: "10.3" },
  { id: "x-052", ch: 10, sec: "10.7", page: 202, type: "calc", level: 2,
    q: "A silt loam furrow field runs at a cutoff ratio of 0.5, so Table 10.4 gives a runoff ratio of 0.24. The well supplies 900 gpm on 12 hr sets, and a continuous pumpback returns runoff to the same field. What pumpback capacity is needed?",
    opts: ["About 216 gpm", "About 284 gpm", "About 386 gpm", "About 164 gpm"], a: 1,
    why: "Qr = Rr Qw/(1 − Rr F) = 0.24 × 900/(1 − 0.24) = 284 gpm (Eq. 10.14), because returned water adds to the inflow and some of it runs off again. Leaving out the denominator gives 216 gpm, using the 0.30 runoff ratio from Example 10.6 gives 386 gpm, and multiplying by (1 − Rr) gives 164 gpm. The pit itself must hold about 205,000 gal (Eq. 10.13).",
    eq: "10.14", calc: "eq-10.13-10.14", fig: null, table: "10.4" },
  { id: "x-053", ch: 10, sec: "10.5", page: 194, type: "scenario", level: 2,
    q: "A grower's meter shows his well delivers 850 gpm to gated pipe on furrows with 0.5% slope. He wants to open as few gates as possible to push water through fast. What is the fewest furrows he should run per set?",
    opts: ["About 22 furrows", "About 85 furrows", "About 43 furrows", "About 17 furrows"], a: 2,
    why: "The maximum nonerosive stream is qmax = 10/S = 10/0.5 = 20 gpm (Eq. 10.10). N = Qt/qs = 850/20 = 42.5, so at least 43 furrows (Eq. 10.9). Using 10/0.25 = 40 gpm gives 22 furrows, 10 gpm streams give 85, and 50 gpm streams give 17, which would erode.",
    eq: "10.10", calc: "eq-10.10", fig: null, table: null },
  { id: "x-054", ch: 10, sec: "10.3", page: 190, type: "calc", level: 2,
    q: "A 1 ft Parshall flume at the head of a furrow field reads 1.2 ft of head, so Q = 3.95 H^1.55 cfs. The water serves 200 furrows spaced 30 in, 1,000 ft long, on 12 hr sets. What gross depth is applied per set?",
    opts: ["About 4.9 in", "About 10.9 in", "About 5.4 in", "About 0.45 in"], a: 2,
    why: "Q = 3.95 × 1.2^1.55 = 5.24 cfs, or 5.24 × 448.8 = 2,350 gpm (Table 3.3). dg = 1,155 × 2,350 × 12/(200 × 30 × 1,000) = 5.4 in (Eq. 10.4). Dropping the exponent gives 4.9 in, using a 15 in spacing gives 10.9 in, and forgetting the 12 hr gives 0.45 in.",
    eq: "10.4", calc: "eq-10.4", fig: null, table: "3.3" },
  { id: "x-055", ch: 10, sec: "10.4", page: 191, type: "scenario", level: 3,
    q: "A furrow grower applies 4.4 in gross per set, the low quarter gets 3.1 in, SWD is 3.0 in and 30% of the inflow runs off. He asks how much a tailwater pit that returns runoff to the same field (Rt = 0.85) would raise his ELQ. What do you tell him?",
    opts: ["From about 68% to about 92%", "From about 68% to 100%", "From about 70% to about 86%", "From about 68% to about 75%"], a: 0,
    why: "Without recovery ELQ = de/dg = 3.0/4.4 = 68%. With closed recovery ELQ = de/(dg − dg Rr Rt) = 3.0/(4.4 − 4.4 × 0.30 × 0.85) = 92% (Eq. 10.6). It cannot reach 100% because 15% of the runoff is lost and some water still percolates. An open system that sends water to another field gives about 86%.",
    eq: "10.6", calc: "eq-10.6-10.7", fig: null, table: null },
  { id: "x-056", ch: 10, sec: "10.3", page: 191, type: "calc", level: 3,
    q: "A level basin 100 ft wide and 400 ft long is fed at 900 gpm. Before irrigation SWD is 3.0 in, and the basin's DU is 0.85. About how long should the inflow run to refill the low quarter?",
    opts: ["About 1.6 hr", "About 1.4 hr", "About 1.2 hr", "About 16 hr"], a: 0,
    why: "The gross depth needed is 3.0/0.85 = 3.53 in. From dg = 96.3 Qt tco/(W L) (Eq. 10.5), tco = 3.53 × 100 × 400/(96.3 × 900) = 1.6 hr. Refilling only the average gives 1.4 hr, multiplying by DU gives 1.2 hr, and 16 hr is a decimal slip.",
    eq: "10.5", calc: "eq-10.5", fig: null, table: null },
  { id: "x-057", ch: 10, sec: "10.5", page: 197, type: "calc", level: 2,
    q: "A furrow set delivers 800 gpm to 80 furrows (30 in spacing, 1,000 ft long) for 12 hr on silt loam with no runoff recovery. The cutoff ratio is 0.75, which gives an infiltration factor of about 0.695 and a runoff ratio of 0.10. SWD is 2.8 in. What is the ELQ?",
    opts: ["About 61%", "About 70%", "About 87%", "About 67%"], a: 0,
    why: "dg = 1,155 × 800 × 12/(80 × 30 × 1,000) = 4.62 in (Eq. 10.4). dLQ = 0.695 × 4.62 = 3.21 in, which exceeds the 2.8 in deficit, so de = 2.8 in and ELQ = 2.8/4.62 = 61%. 70% is the infiltration factor, 87% is SWD/dLQ, and 67% subtracts the runoff as if it were recovered.",
    eq: "10.12", calc: "eq-10.12", fig: null, table: "10.3" },
  { id: "x-058", ch: 5, sec: "5.3", page: 92, type: "scenario", level: 2,
    q: "A grower ordered water equal to 4.0 in over his field at the headgate, but the flume at the field measured only 3.4 in. His furrows run at about 65% application efficiency. What are his conveyance efficiency and overall efficiency from headgate to root zone?",
    opts: ["Conveyance about 85%, overall about 65%", "Conveyance about 118%, overall about 77%", "Conveyance about 85%, overall about 55%", "Conveyance about 60%, overall about 39%"], a: 2,
    why: "Ec = 3.4/4.0 = 85% (Eq. 5.19). Overall efficiency is the product of the steps, 0.85 × 0.65 = 55%, so only about 2.2 in of the 4.0 in ordered is stored for the crop. Reporting the field efficiency alone hides the ditch loss, and 118% inverts the ratio.",
    eq: "5.19", calc: "eq-5.19", fig: null, table: null },
  { id: "x-059", ch: 13, sec: "13.2", page: 280, type: "scenario", level: 2,
    q: "A grower's 1,300 ft pivot gets 800 gpm from his well. He plans to add an end gun that throws 100 ft beyond the last tower in the corners, with no extra well capacity. He asks what that does to his system capacity. What do you tell him?",
    opts: ["Area grows from about 122 to 141 ac, so capacity falls to about 5.7 gpm/ac", "Capacity stays at 6.6 gpm/ac, because the end gun only runs in the corners", "Area grows from about 122 to 132 ac, so capacity rises because the gun adds flow", "Area grows from about 122 to 132 ac, so capacity falls from about 6.6 to 6.1 gpm/ac"], a: 3,
    why: "Without the gun the circle is π × 1,300²/43,560 = 122 ac, or 800/122 = 6.6 gpm/ac. Eq. 13.2 gives about 132 ac with a 100 ft end gun in the corners, so the same 800 gpm becomes 6.1 gpm/ac, or about 0.32 in/d gross instead of 0.35 in/d (18.86 gpm/ac = 1 in/d, Chapter 5). Counting a full 1,400 ft circle overstates the area at 141 ac, because the gun only runs in the corners.",
    eq: "13.2", calc: "eq-13.2", fig: null, table: null },
  { id: "x-060", ch: 5, sec: "5.3", page: 94, type: "scenario", level: 2,
    q: "A ditch rider asks whether to pipe an unlined lateral through loam. It is 2,640 ft long with about 4 ft² of wetted perimeter per foot, carries 3 cfs, and runs 150 days a year. Using Figure 5.8 and 1% vegetation loss per mile, about how much water does it lose each year?",
    opts: ["About 51 ac-ft", "About 4.5 ac-ft", "About 55 ac-ft", "About 21 ac-ft"], a: 2,
    why: "Figure 5.8 gives about 1.4 ft³/ft²/d for loam, so seepage = 4 × 2,640 × 1.4 × 150/43,560 = 51 ac-ft. Vegetation loss = 1% × (2,640/5,280) × 3 cfs × 1 ac-in/hr per cfs × 24 hr = 0.36 ac-in/d, or 4.5 ac-ft over 150 days. Total is about 55 ac-ft of the 900 ac-ft delivered, about 6%. 51 ac-ft is seepage alone and 21 ac-ft is the Example 5.6 answer for a different ditch.",
    eq: "5.19", calc: "ditch-seepage", fig: "5.8", table: null },
  { id: "x-061", ch: 12, sec: "12.2", page: 238, type: "calc", level: 3,
    q: "A wheel line has 9/64 in nozzles (discharge coefficient 0.96) running at 45 psi, spaced 40 ft along the line, and is moved 50 ft each set. Sets run 11.5 hr and application efficiency is 75%. What net depth does each set store?",
    opts: ["About 2.1 in", "About 1.6 in", "About 2.8 in", "About 1.2 in"], a: 1,
    why: "q = 29.82 × 0.96 × (9/64)² × √45 = 3.80 gpm (Eq. 11.1). Ar = 96.3 × 3.80/(40 × 50) = 0.183 in/hr, so dg = 0.183 × 11.5 = 2.10 in (Eq. 12.1). Net = 0.75 × 2.10 = 1.58 in (Eq. 12.2). 2.1 in is the gross depth, 2.8 in divides by efficiency, and 1.2 in applies efficiency twice.",
    eq: "12.1", calc: "eq-12.1", fig: null, table: null },
  { id: "x-062", ch: 11, sec: "11.3", page: 219, type: "scenario", level: 2,
    q: "A grower set up a solid set with 6 gpm sprinklers on a 30 ft × 50 ft spacing on bare silty clay loam with a 6% slope. Water runs off within the first hour. What do you tell him?",
    opts: ["The rate is about 0.39 in/hr, within the 0.25 to 0.50 in/hr range, so the runoff must be from a leak", "The rate is about 0.19 in/hr, so shorten the sets to stop runoff", "The rate is about 0.39 in/hr, almost twice the 0.20 in/hr maximum for this soil and slope, so use smaller nozzles", "The rate is about 0.39 in/hr, so just shorten the set time to fix the rate"], a: 2,
    why: "Ar = 96.3 × 6/(30 × 50) = 0.39 in/hr (Eq. 11.2). Table 11.4 allows 0.08 to 0.20 in/hr for unprotected fine soils on 5 to 8% slopes. Shorter sets cut depth, not rate, so runoff still starts early. Smaller nozzles (or residue cover) bring the rate down, and the 0.25 to 0.50 range applies to medium soils.",
    eq: "11.2", calc: "tab-11.4", fig: null, table: "11.4" },
  { id: "x-063", ch: 12, sec: "12.2", page: 239, type: "scenario", level: 3,
    q: "A wheel line stores about 1.6 in net per 11.5 hr set and gets around the field every 8 days. Peak crop ET is 0.25 in/d, and the 3 ft root zone holds 1.8 in/ft with 50% allowable depletion. The grower asks if the line can keep up. What do you tell him?",
    opts: ["Yes, 1.6 in is under the 2.7 in allowable depletion, so the crop is safe", "No, 8 days at 0.25 in/d needs 2.0 in net, so he needs longer sets or larger nozzles", "Yes, 1.6 in every 8 days is 0.20 in/d, more than enough at peak", "No, he needs 2.7 in net every set to match the allowable depletion"], a: 1,
    why: "Required net depth = interval × use = 8 × 0.25 = 2.0 in (Eq. 12.3). AD = 3 × 1.8 × 0.5 = 2.7 in (Eq. 12.4), so the soil can hold a 2.0 in refill, but the line only puts back 1.6 in. The deficit grows about 0.4 in each cycle. Staying under AD is necessary but does not prove the system keeps up.",
    eq: "12.3", calc: "eq-12.3", fig: null, table: null },
  { id: "x-064", ch: 12, sec: "12.5", page: 268, type: "calc", level: 2,
    q: "A traveler gun discharges 500 gpm on 250 ft lanes. SWD is 1.6 in and application efficiency is 75%. What travel speed refills the deficit?",
    opts: ["About 120 ft/hr", "About 90 ft/hr", "About 68 ft/hr", "About 100 ft/hr"], a: 1,
    why: "Gross depth = 1.6/0.75 = 2.13 in. From dg = 96.3 qs/(Wp vt) (Eq. 12.11), vt = 96.3 × 500/(250 × 2.13) = 90 ft/hr. Designing for the net 1.6 in gives 120 ft/hr, multiplying by efficiency gives 68 ft/hr, and 100 ft/hr applies only 1.9 in gross.",
    eq: "12.11", calc: "eq-12.11", fig: null, table: null },
  { id: "x-065", ch: 11, sec: "11.3", page: 213, type: "scenario", level: 2,
    q: "A solid set was designed for 7.0 gpm sprinklers at 50 psi. Since a new pivot was added to the same mainline, the gauge at the set reads 40 psi. The grower still runs 12 hr sets. What do you tell him?",
    opts: ["Each head now puts out about 5.6 gpm, 20% less, the same as the pressure drop", "Flow does not change with pressure, only the throw distance does", "Each head now puts out about 7.8 gpm, because lower pressure gives bigger drops", "Each head now puts out about 6.3 gpm, about 11% less, so sets need about 13.4 hr for the same depth"], a: 3,
    why: "Nozzle flow goes with the square root of pressure (Eq. 11.1): 7.0 × √(40/50) = 6.26 gpm, an 11% drop. To apply the same depth he needs 12/0.894 = 13.4 hr, and the lower pressure may also hurt the pattern. The extra friction from the shared mainline (Chapter 8) is the root cause, so check pipe size or add pumping capacity.",
    eq: "11.1", calc: "eq-11.1-ratio", fig: null, table: null },
  { id: "x-066", ch: 12, sec: "12.5", page: 268, type: "calc", level: 3,
    q: "One traveler must cover 8 lanes, each 250 ft wide and 1,200 ft long. The net capacity needed is 4.8 gpm/ac, application efficiency is 70%, sets are 12 hr with 11 hr of watering, and the 4.5 day cycle includes 0.5 day of downtime. What gun discharge is needed?",
    opts: ["About 378 gpm", "About 325 gpm", "About 464 gpm", "About 58 gpm"], a: 2,
    why: "Each lane is 250 × 1,200/43,560 = 6.89 ac. qs = (4.8 × 6.89/0.70) × 8 × (12/11) × (4.5/4.0) = 464 gpm (Eq. 12.13). Skipping the time factors gives 378 gpm, leaving out efficiency gives 325 gpm, and forgetting the 8 lanes gives 58 gpm.",
    eq: "12.13", calc: "eq-12.13", fig: null, table: null },
  { id: "x-067", ch: 3, sec: "3.4", page: 45, type: "calc", level: 2,
    q: "A border field of 12 acres is fed through a rectangular weir with a 1.5 ft crest and no side contraction, Q = 3.33 L H^1.5 cfs. The head holds at 0.6 ft for an 18 hr set. About what gross depth went on?",
    opts: ["About 4.5 in", "About 3.5 in", "About 2.1 in", "About 0.19 in"], a: 1,
    why: "Q = 3.33 × 1.5 × 0.6^1.5 = 2.32 cfs, and 1 cfs is about 1 ac-in/hr (Table 3.1). Depth = Q t/A = 2.32 × 18/12 = 3.5 in (Eq. 3.3). Dropping the 1.5 exponent gives 4.5 in, using 2.5 gives 2.1 in, and forgetting the 18 hr gives 0.19 in.",
    eq: "3.3", calc: "tab-3.2", fig: null, table: "3.2" },
  { id: "x-068", ch: 5, sec: "5.5", page: 95, type: "calc", level: 3,
    q: "A 126 acre pivot sits on sand with AWC 0.10 in/in, a 40 in root zone and 50% allowable depletion. Maximum monthly crop ET is 9 in. With ELQ 85% and 5% downtime, about what well flow does the pivot need?",
    opts: ["About 980 gpm", "About 1,030 gpm", "About 880 gpm", "About 930 gpm"], a: 1,
    why: "AD = 0.10 × 40 × 0.5 = 2.0 in, and Table 5.3 gives a peak of 0.35 in/d for 9 in/mo at AD 2.0. Cg = 0.35 × 18.86/(0.85 × 0.95) = 8.2 gpm/ac and Q = 8.2 × 126 = 1,030 gpm (Eq. 5.20). Leaving out downtime gives 980 gpm, using the monthly average of 0.30 in/d gives 880 gpm, and multiplying by (1 − Dt) gives 930 gpm.",
    eq: "5.20", calc: "eq-5.20", fig: null, table: "5.3" },
  { id: "x-069", ch: 5, sec: "5.6", page: 99, type: "scenario", level: 3,
    q: "One well feeds a main canal (90% efficient) that splits to two furrow fields with tailwater return, both at ELQ 80%. Field 1 is 125 ac on a lined lateral (95%) and Field 2 is 60 ac on an earthen lateral (80%). Net capacity is 0.30 in/d and the system is down 5% of the time. What must the well produce?",
    opts: ["About 1,380 gpm", "About 1,540 gpm", "About 1,160 gpm", "About 1,710 gpm"], a: 3,
    why: "Cg = 0.30 × 18.86/(0.80 × 0.95) = 7.44 gpm/ac (Eq. 5.20). Field flows are 930 and 447 gpm, which become 930/0.95 = 979 and 447/0.80 = 558 gpm at the laterals (Eq. 5.21). The well must supply (979 + 558)/0.90 = 1,710 gpm. Stopping at the field flows gives 1,380 gpm, skipping the main canal gives 1,540 gpm, and using net capacity only gives about 1,160 gpm.",
    eq: "5.21", calc: "farm-capacity", fig: null, table: null },
  { id: "x-070", ch: 5, sec: "5.3", page: 90, type: "calc", level: 2,
    q: "A park lawn has a landscape coefficient of 0.8 and ETo is 0.25 in/d. It is watered every 2 days with 3.0 gpm rotors on a 35 ft square spacing. An audit gives SC = 1.43. How long should each zone run?",
    opts: ["About 1.7 hr", "About 1.2 hr", "About 3.0 hr", "About 2.4 hr"], a: 3,
    why: "ET = 0.8 × 0.25 = 0.20 in/d, so 0.40 in every 2 days (Eq. 4.14). Ar = 96.3 × 3.0/(35 × 35) = 0.236 in/hr (Eq. 3.5). Run time = 0.40/0.236 × 1.43 = 2.4 hr (Eq. 5.13). Leaving out SC gives 1.7 hr, dividing by SC gives 1.2 hr, and using ETo instead of landscape ET gives 3.0 hr.",
    eq: "5.13", calc: "eq-5.13", fig: null, table: null },
  { id: "x-071", ch: 2, sec: "2.9", page: 23, type: "scenario", level: 2,
    q: "A grower applied 2.0 in with a pivot (DU 0.80). His deficits are 0.10 in/in in the top foot, 0.08 in/in in the second foot and 0.04 in/in below. He says, \"Two inches got my whole 24 inch root zone wet.\" What do you tell him?",
    opts: ["He is right, 2.0 in fills the top 24 in everywhere", "On average it wet about 20 in, because 2.0 in at 0.10 in/in is 20 in", "On average it wet about 22 in, and the low quarter only about 17 in, so the bottom of the root zone is still dry in places", "It wet about 30 in on average, so some water drained below the roots"], a: 2,
    why: "The top foot takes 0.10 × 12 = 1.2 in. The remaining 0.8 in fills 0.8/0.08 = 10 in of the second layer, so the front reaches 22 in. The low quarter gets 0.80 × 2.0 = 1.6 in, which after the top 1.2 in reaches only 0.4/0.08 = 5 in more, or 17 in. Using one deficit for all layers gives 20 in.",
    eq: "2.13", calc: "wetting-depth", fig: null, table: null },
  { id: "x-072", ch: 13, sec: "13.3", page: 285, type: "scenario", level: 2,
    q: "A grower is choosing between a 1,300 ft pivot and a 1,300 ft linear move, each with 1,000 gpm and 45 ft wetted diameter sprinklers, on a soil prone to runoff. He asks which has the lower peak application rate. What do you tell him?",
    opts: ["The pivot, about 2.1 in/hr at the end, versus about 4.2 in/hr for the linear", "They are the same, because flow and wetted diameter are the same", "The linear, about 2.1 in/hr, versus about 4.2 in/hr at the outer end of the pivot", "The linear, about 0.35 in/hr, versus about 0.70 in/hr for the pivot"], a: 2,
    why: "Linear: Ap = 122.5 Q/(L Dc) = 122.5 × 1,000/(1,300 × 45) = 2.1 in/hr (Eq. 13.6). Pivot: 1,000 gpm on 122 ac is 8.2 gpm/ac, and at the end Ap = 0.0177 × 8.2 × 1,300/45 = 4.2 in/hr (Eq. 13.4). The pivot end must water the largest area per foot of lateral, so its rate is about double the linear's.",
    eq: "13.6", calc: "eq-13.6", fig: null, table: null },
  { id: "x-073", ch: 12, sec: "12.5", page: 268, type: "scenario", level: 3,
    q: "A traveler gun putting out 500 gpm with a 230 ft wetted radius runs a 270° arc on bare silty clay loam with a 3% slope. Water ponds and runs off behind the cart. What do you tell the grower?",
    opts: ["The average rate is about 0.39 in/hr, above the 0.25 in/hr maximum, so use a smaller nozzle or a lighter, faster pass", "The average rate is about 0.29 in/hr, just inside the 0.25 to 0.50 in/hr range, so the runoff is from the hose", "The average rate is about 0.39 in/hr, which is fine for any soil under 5% slope", "The average rate is about 0.10 in/hr, so runoff must be from wheel tracks"], a: 0,
    why: "Ar = 11,035 × 500/(270 × 230²) = 0.39 in/hr (Eq. 12.12). Table 11.4 allows 0.10 to 0.25 in/hr for unprotected fine soils at 0 to 5% slope. A full 360° circle would give 0.29 in/hr, still above the limit, which is why travelers usually run a part circle and can still cause runoff on heavy soils. Smaller nozzles or faster travel to reduce depth per pass help.",
    eq: "12.12", calc: "eq-12.12", fig: null, table: "11.4" },
  { id: "x-074", ch: 13, sec: "13.2", page: 282, type: "scenario", level: 2,
    q: "A grower's pivot has 32 psi at the inlet, a lateral friction loss of 6 psi per 1,000 ft, and 20 psi pressure regulators on every drop. The 1,300 ft lateral climbs to a hilltop 15 ft above the pivot point. What pressure is at the last regulator inlet on the hilltop?",
    opts: ["About 17.7 psi, below the 20 psi regulators, so they cannot regulate there", "About 24.2 psi, so the regulators work fine", "About 9.2 psi, so the end sprinklers barely turn", "About 25.5 psi, because elevation helps on the way up"], a: 0,
    why: "Friction to the end is 6 × 1,300/1,000 × fp = 7.8 psi (fp = 1 at the end, Eq. 13.3). Elevation costs 0.433 × 15 = 6.5 psi. Pressure = 32 − 7.8 − 6.5 = 17.7 psi, below the regulator setting, so the end discharge drops on the hill. Leaving out the hill gives 24.2 psi, and treating 15 ft as 15 psi gives 9.2 psi.",
    eq: "13.3", calc: "eq-13.3", fig: null, table: null },
  { id: "x-075", ch: 2, sec: "2.3", page: 13, type: "scenario", level: 3,
    q: "A grower brings in a composite sample from his 24 in root zone with a gravimetric water content of 0.14. Bulk density is 1.40 g/cm³, field capacity is 0.30 and wilting point is 0.14 (volumetric), and he uses 50% allowable depletion. What do you tell him?",
    opts: ["SWD is about 3.8 in, the soil is at wilting point", "SWD is about 2.5 in, still within the 3.8 in TAW, so he can wait", "SWD is about 2.5 in, already past the 1.9 in allowable depletion, so irrigate now", "SWD is about 1.3 in, still within the allowable depletion"], a: 2,
    why: "θv = θm × ρb/ρw = 0.14 × 1.40 = 0.196 (Eq. 2.5). SWD = (0.30 − 0.196) × 24 = 2.5 in (Eq. 2.13). TAW = 0.16 × 24 = 3.84 in and AD = 1.92 in, so the crop is already past the trigger. Treating 0.14 as volumetric puts the soil at wilting point, and comparing to TAW instead of AD hides the stress.",
    eq: "2.5", calc: "eq-2.5", fig: null, table: null },
  { id: "x-076", ch: 11, sec: "11.4", page: 221, type: "calc", level: 3,
    q: "A level hand-move lateral should average 45 psi and loses 9 psi to friction. The mainline from the pump to the lateral valve loses 4.5 psi and climbs 10 ft. What pressure should the pump deliver?",
    opts: ["About 54 psi", "About 57 psi", "About 66 psi", "About 61 psi"], a: 3,
    why: "For a level lateral the inlet pressure is Pa + 3/4 Pl = 45 + 0.75 × 9 = 51.75 psi (Eq. 11.6). Add the mainline loss of 4.5 psi and the rise of 10/2.31 = 4.3 psi: 51.75 + 4.5 + 4.3 = 61 psi. Starting from the 45 psi average gives 54 psi, leaving out the rise gives 57 psi, and adding the 10 ft as if it were psi gives about 66 psi.",
    eq: "11.6", calc: "eq-11.5-11.9", fig: null, table: null },
  { id: "x-077", ch: 15, sec: "15.4", page: 332, type: "scenario", level: 3,
    q: "A grower fertigates 30 lb N/ac through his pivot. A recent catch-can test gave DU = 0.75. He asks if every part of the field got 30 lb. What do you tell him?",
    opts: ["No, chemical follows the water, so the low quarter got only about 22.5 lb N/ac", "Yes, the injection rate is set per acre, so every acre gets 30 lb", "No, the low quarter got about 40 lb N/ac because the wettest areas dilute it", "Yes, as long as he flushes the lateral after injecting"], a: 0,
    why: "Injected chemical is spread by the same water, so it is applied with the same uniformity as the irrigation. The low quarter average is DU × average = 0.75 × 30 = 22.5 lb N/ac (Eq. 5.8 logic). Fixing nozzles and pressure improves both water and nutrient distribution. Dividing by DU (40 lb) is the wrong direction for the low quarter.",
    eq: "5.8", calc: "eq-5.8", fig: null, table: null },
  { id: "x-078", ch: 14, sec: "14.6", page: 312, type: "calc", level: 2,
    q: "An emitter test gives 0.88 gph at 5 psi and 1.05 gph at 10 psi. What flow should you expect at 7 psi?",
    opts: ["About 0.74 gph", "About 0.96 gph", "About 0.88 gph", "About 1.15 gph"], a: 1,
    why: "x = log(0.88/1.05)/log(5/10) = 0.25 and K = 1.05/23.1^0.25 = 0.47 with h in ft (Eq. 14.4, 2.31 ft per psi). At 7 psi (16.2 ft), q = 0.47 × 16.2^0.25 = 0.96 gph (Eq. 14.3). Assuming a linear emitter (x = 1) gives 0.74 gph, a typical orifice (x = 0.5) gives 0.88 gph, and inverting the pressure ratio gives 1.15 gph.",
    eq: "14.4", calc: "eq-14.4", fig: null, table: null },
  { id: "x-079", ch: 6, sec: "6.4", page: 116, type: "scenario", level: 2,
    q: "A grower's checkbook showed SWD = 0.8 in when 1.5 in of rain fell overnight. ET is running 0.25 in/d and his allowable depletion is 1.8 in. He says, \"That rain should carry me a week.\" How long until he hits the trigger again?",
    opts: ["About 6 days, because only 0.8 in of the rain could be stored", "About 9 days, because all 1.5 in counts", "About 4 days, because rain is only half effective", "About 3 days, because the deficit is back to 0.8 in by then"], a: 0,
    why: "Effective rain is limited to the deficit, so only 0.8 in is stored and the profile is at field capacity (Eq. 6.21). The extra 0.7 in ran off or drained. After the day's ET, SWD = 0.25 in, and the trigger at 1.8 in comes about (1.8 − 0.25)/0.25 = 6.2 days later, so about 6 days. Counting the full 1.5 in adds three phantom days.",
    eq: "6.21", calc: "eq-6.18-6.25", fig: null, table: null },
  { id: "x-080", ch: 8, sec: "8.7", page: 167, type: "scenario", level: 3,
    q: "A grower is budgeting pumping for a 130 acre pivot. Seasonal crop ET is 22 in, effective rain is 6 in, and ELQ is 85%. His electric plant has TDH of 260 ft and PR 0.90, and power costs $0.10/kWh. About what will the season's pumping cost?",
    opts: ["About $9,100", "About $7,800", "About $12,600", "About $8,200"], a: 0,
    why: "Gross = (22 − 6)/0.85 = 18.8 in, or 18.8 × 130 = 2,450 ac-in. Energy is 0.1157 × 260/(0.885 × 0.90) = 37.3 kWh per ac-in, or $3.73, so the season costs 2,450 × $3.73 = $9,100 (Eq. 8.22). Pricing the net 16 in gives $7,800, ignoring rain gives $12,600, and ignoring PR gives $8,200.",
    eq: "8.22", calc: "eq-8.22", fig: null, table: null }
]);
